import React, { useState } from 'react';

function ComboScreen({ ticketTotal = 0, onBack, onNext }) {
  const combos = [
    { id: 'popcorn-small', name: 'Bắp nhỏ', price: 30000 },
    { id: 'popcorn-large', name: 'Bắp lớn', price: 50000 },
    { id: 'drink', name: 'Nước', price: 25000 }
  ];

  const [counts, setCounts] = useState({});

  const changeCount = (id, delta) => {
    const prev = counts[id] || 0;
    const next = Math.max(0, prev + delta);
    setCounts({ ...counts, [id]: next });
  };

  const comboTotal = combos.reduce((sum, c) => sum + (counts[c.id] || 0) * c.price, 0);

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại chọn ghế</button>

      <div className="card p-4 shadow-sm border-0 bg-white" style={{ backgroundColor: '#faf5ff' }}>
        <h3 className="fw-bold mb-3" style={{ color: '#7c3aed' }}>Chọn Combo Bắp & Nước</h3>

        <div className="row g-3">
          {combos.map(c => (
            <div key={c.id} className="col-12 d-flex align-items-center justify-content-between p-3" style={{ borderRadius: 12, background: '#fff', border: '1px solid #eef2ff' }}>
              <div>
                <div className="fw-bold">{c.name}</div>
                <div className="text-secondary small">{c.price.toLocaleString()}đ</div>
              </div>
              <div className="d-flex align-items-center gap-2">
                <button className="btn btn-sm" onClick={() => changeCount(c.id, -1)}>-</button>
                <div style={{ minWidth: 28, textAlign: 'center' }}>{counts[c.id] || 0}</div>
                <button className="btn btn-sm" onClick={() => changeCount(c.id, 1)}>+</button>
              </div>
            </div>
          ))}
        </div>

        <div className="d-flex justify-content-between align-items-center mt-4">
          <div className="fw-bold">Tổng Combo:</div>
          <div className="fs-5 fw-bold" style={{ color: '#7c3aed' }}>{comboTotal.toLocaleString()}đ</div>
        </div>

        <div className="d-flex gap-2 mt-4">
          <button className="btn w-50 fw-bold py-2" style={{ background: '#f3f4f6', borderRadius: 8 }} onClick={onBack}>Quay lại</button>
          <button className="btn w-50 fw-bold text-white" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', borderRadius: 8 }} onClick={() => onNext({ comboCounts: counts, comboTotal })}>Tiếp tục thanh toán</button>
        </div>
      </div>
    </div>
  );
}

export default ComboScreen;
